<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  :root {
    --bg: #0e1116;
    --panel: #161b22;
    --accent: #4ade80;
    --food: #f87171;
    --border: #2a313c;
    --text: #e6edf3;
    --muted: #8b949e;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: radial-gradient(circle at 50% 0%, #1a2030 0%, #0e1116 60%);
    color: var(--text);
    font-family: -apple-system, system-ui, "Segoe UI", Roboto, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    padding: 20px;
  }
  h1 { margin: 0; font-weight: 600; letter-spacing: 0.5px; font-size: 22px; }
  .wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
  }
  .hud {
    display: flex;
    align-items: center;
    gap: 24px;
    width: 100%;
    justify-content: space-between;
    padding: 10px 16px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
  }
  .score-label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 1px; }
  #score { font-size: 24px; font-weight: 700; color: var(--accent); line-height: 1.1; }
  .status { font-size: 13px; color: var(--muted); }
  canvas#snake {
    background: #0a0e14;
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5), inset 0 0 60px rgba(74,222,128,0.03);
    display: block;
    image-rendering: pixelated;
  }
  .controls { display: flex; gap: 10px; }
  button {
    font: inherit;
    padding: 9px 18px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: var(--panel);
    color: var(--text);
    cursor: pointer;
    transition: transform 0.08s, background 0.15s, border-color 0.15s;
    min-width: 90px;
  }
  button:hover { background: #1f2630; border-color: #3a4350; }
  button:active { transform: translateY(1px); }
  button.primary { background: var(--accent); color: #06210f; border-color: var(--accent); font-weight: 600; }
  button.primary:hover { background: #5eea8f; }
  .hint { font-size: 12px; color: var(--muted); }
</style>
</head>
<body>
  <h1>Snake</h1>
  <div class="wrap">
    <div class="hud">
      <div>
        <div class="score-label">Score</div>
        <div id="score">0</div>
      </div>
      <div class="status" id="status">Ready</div>
    </div>
    <canvas id="snake" width="400" height="400"></canvas>
    <div class="controls">
      <button id="start" class="primary">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
    </div>
    <div class="hint">Arrow keys to steer · Space to pause/resume</div>
  </div>
<script>
(function(){
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const CELL = 20;
  const W = 20, H = 20;          // grid cells (>= 10), board = 400x400 CSS px
  canvas.width  = W * CELL;
  canvas.height = H * CELL;

  const DELTAS = { up:[0,-1], down:[0,1], left:[-1,0], right:[1,0] };
  const OPP    = { up:'down', down:'up', left:'right', right:'left' };

  let body, dir, queuedDir, food, alive, scoreVal;
  let loopId = null;
  const SPEED = 110; // ms per auto tick

  function placeFood(){
    const free = [];
    for (let y=0;y<H;y++) for (let x=0;x<W;x++){
      if (!body.some(s=>s[0]===x&&s[1]===y)) free.push([x,y]);
    }
    if (free.length===0){ food=null; return; }
    food = free[Math.floor(Math.random()*free.length)];
  }

  function resetState(){
    body = [[7,10],[6,10],[5,10]]; // head first, length 3
    dir = 'right';
    queuedDir = null;
    alive = true;
    scoreVal = 0;
    placeFood();
    updateHud();
    draw();
  }

  function setFood(x,y){
    if (typeof x!=='number'||typeof y!=='number') return;
    if (x<0||x>=W||y<0||y>=H) return;
    food = [x,y];
    draw();
  }

  function setDir(d){
    if (!alive) return;
    if (!DELTAS[d]) return;
    if (OPP[dir] === d) return;   // ignore 180° reversal vs current heading
    queuedDir = d;
  }

  function tick(){
    if (!alive) return;
    if (queuedDir){ dir = queuedDir; queuedDir = null; }
    const [dx,dy] = DELTAS[dir];
    const head = body[0];
    const nx = head[0]+dx, ny = head[1]+dy;

    // wall collision
    if (nx<0||nx>=W||ny<0||ny>=H){ alive=false; draw(); onDeath(); return; }

    const willEat = food && nx===food[0] && ny===food[1];
    // self collision (tail will move out unless eating)
    const checkBody = willEat ? body : body.slice(0, body.length-1);
    for (const s of checkBody){
      if (s[0]===nx && s[1]===ny){ alive=false; draw(); onDeath(); return; }
    }

    body.unshift([nx,ny]);
    if (willEat){ scoreVal++; placeFood(); updateHud(); }
    else { body.pop(); }
    draw();
  }

  function onDeath(){
    stopLoop();
    const st = document.getElementById('status');
    st.textContent = 'Game Over — press Reset';
    st.style.color = '#f87171';
  }

  function updateHud(){
    document.getElementById('score').textContent = scoreVal;
    const st = document.getElementById('status');
    if (alive){
      st.textContent = loopId ? 'Running' : 'Ready';
      st.style.color = '';
    }
  }

  function start(){
    if (!alive) return;
    if (loopId) return;
    loopId = setInterval(()=>{ tick(); }, SPEED);
    updateHud();
  }
  function pause(){
    if (loopId){ clearInterval(loopId); loopId=null; }
    if (alive){
      document.getElementById('status').textContent = 'Paused';
    }
  }
  function stopLoop(){ if (loopId){ clearInterval(loopId); loopId=null; } }

  function resetGame(){
    stopLoop();
    resetState();
    document.getElementById('status').textContent = 'Ready';
    document.getElementById('status').style.color='';
  }

  // ---------- Drawing ----------
  function roundRect(c,x,y,w,h,r){
    r = Math.min(r, w/2, h/2);
    c.beginPath();
    c.moveTo(x+r,y);
    c.arcTo(x+w,y,x+w,y+h,r);
    c.arcTo(x+w,y+h,x,y+h,r);
    c.arcTo(x,y+h,x,y,r);
    c.arcTo(x,y,x+w,y,r);
    c.closePath();
  }

  function draw(){
    // background
    ctx.fillStyle = '#0a0e14';
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;
    for (let i=1;i<W;i++){
      ctx.beginPath(); ctx.moveTo(i*CELL+0.5,0); ctx.lineTo(i*CELL+0.5,canvas.height); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0,i*CELL+0.5); ctx.lineTo(canvas.width,i*CELL+0.5); ctx.stroke();
    }

    // food
    if (food){
      const [fx,fy] = food;
      const cx = fx*CELL+CELL/2, cy = fy*CELL+CELL/2;
      ctx.save();
      ctx.shadowColor = 'rgba(248,113,113,0.85)';
      ctx.shadowBlur = 14;
      ctx.fillStyle = '#f87171';
      ctx.beginPath();
      ctx.arc(cx, cy, CELL*0.34, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.beginPath();
      ctx.arc(cx-2.5, cy-2.5, CELL*0.1, 0, Math.PI*2);
      ctx.fill();
    }

    // snake (draw tail-first so head sits on top)
    for (let i=body.length-1;i>=0;i--){
      const [x,y] = body[i];
      const px = x*CELL, py = y*CELL;
      const isHead = i===0;
      const pad = 1.5;
      ctx.fillStyle = !alive ? '#6b7280' : (isHead ? '#5eea8f' : '#4ade80');
      roundRect(ctx, px+pad, py+pad, CELL-pad*2, CELL-pad*2, 5);
      ctx.fill();
      if (isHead){
        // eyes oriented to heading
        ctx.fillStyle = '#06210f';
        const [dx,dy] = DELTAS[dir];
        const ex = px+CELL/2, ey = py+CELL/2;
        const off = 3, eo = 4;
        let e1x,e1y,e2x,e2y;
        if (dx!==0){
          e1x = ex+dx*off; e1y = ey-eo;
          e2x = ex+dx*off; e2y = ey+eo;
        } else {
          e1x = ex-eo; e1y = ey+dy*off;
          e2x = ex+eo; e2y = ey+dy*off;
        }
        ctx.beginPath(); ctx.arc(e1x,e1y,1.7,0,Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(e2x,e2y,1.7,0,Math.PI*2); ctx.fill();
      }
    }

    // death overlay
    if (!alive){
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(0,0,canvas.width,canvas.height);
      ctx.fillStyle = '#f87171';
      ctx.font = 'bold 28px system-ui, sans-serif';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('Game Over', canvas.width/2, canvas.height/2-10);
      ctx.fillStyle = '#e6edf3';
      ctx.font = '14px system-ui, sans-serif';
      ctx.fillText('Score: '+scoreVal, canvas.width/2, canvas.height/2+18);
    }
  }

  // ---------- Input ----------
  const keyMap = {ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};
  window.addEventListener('keydown', (e)=>{
    if (keyMap[e.key]){ e.preventDefault(); setDir(keyMap[e.key]); }
    else if (e.key===' '){ e.preventDefault(); loopId ? pause() : start(); }
  });
  document.getElementById('start').addEventListener('click', start);
  document.getElementById('pause').addEventListener('click', pause);
  document.getElementById('reset').addEventListener('click', resetGame);

  // ---------- Public API ----------
  window.game = {
    w: W,
    h: H,
    reset: resetGame,
    tick,
    setDir,
    setFood,
    snake:  () => body.map(s => [s[0], s[1]]),
    food:   () => food ? [food[0], food[1]] : null,
    alive:  () => !!alive,
    score:  () => scoreVal,
  };

  // initial board
  resetGame();
})();
</script>
</body>
</html>
